import{GEOMETRY_PINS as P}from'./geometry-pins.mjs';
const loaded=new WeakMap(),sha=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(v=>v.toString(16).padStart(2,'0')).join('');
export async function loadSelectedGameplayGeometry({readBytes,signal}={}){if(typeof readBytes!=='function')throw Error('PINNED_GEOMETRY_READER_REQUIRED');const read=async p=>{if(signal?.aborted)throw Error('GAMEPLAY_LOAD_ABORTED');const b=await readBytes(p),copy=b instanceof ArrayBuffer?new Uint8Array(b.slice(0)):new Uint8Array(b);if(copy.length!==p.bytes||await sha(copy)!==p.sha256)throw Error('GAMEPLAY_GEOMETRY_PIN_MISMATCH');if(signal?.aborted)throw Error('GAMEPLAY_LOAD_ABORTED');return copy};await read(P.selection);const maps=new Map();for(const m of P.maps){const safe=await read(m.selectedSolidSafe),interactions=[];for(const i of m.interactions)interactions.push({...i,mask:await read(i.approach)});maps.set(m.mapId,{safe,interactions})}const result=Object.freeze({});loaded.set(result,maps);return result}
export function selectedGameplayMap(geometry,mapId){const m=loaded.get(geometry)?.get(mapId);if(!m)throw Error('REGISTERED_GAMEPLAY_GEOMETRY_REQUIRED');return{safeMask:()=>new Uint8Array(m.safe),pointAt:([x,y],facing)=>Number.isInteger(x)&&Number.isInteger(y)&&x>=0&&x<1536&&y>=0&&y<1024?(()=>{const i=m.interactions.find(i=>i.requiredFacing===facing&&i.mask[y*1536+x]===1);return i?Object.freeze({pointId:i.pointId,kind:i.kind}):null})():null}}
